def add_platform(articles, extra, lang):
    if not any(a['slug'] == PLATFORM_ART[lang]['slug'] for a in articles):
        articles.append(dict(PLATFORM_ART[lang]))
    for k, qa in PLATFORM_FAQ[lang].items():
        have = {q for q, _ in extra[k]['faq']}
        extra[k]['faq'] = list(extra[k]['faq']) + [x for x in qa if x[0] not in have]


